Prepare the data
I calculate total compensation and compensation for the top three players in each club-season, then join these summaries to regular-season performance. The salary file uses only the latest available release each year to avoid counting players twice.


Code
library(tidyverse)
set.seed(47)

salaries &lt;- read_csv("data/mls_salary_snapshots.csv")
performance &lt;- read_csv("data/mls_team_performance.csv")
teams &lt;- read_csv("data/mls_teams.csv")

payroll &lt;- salaries |&gt;
  group_by(year, team_id) |&gt;
  summarize(total_pay = sum(guaranteed_compensation),
            players = n(), .groups = "drop")

top_three &lt;- salaries |&gt;
  group_by(year, team_id) |&gt;
  slice_max(guaranteed_compensation, n = 3, with_ties = FALSE) |&gt;
  summarize(top_three_pay = sum(guaranteed_compensation),
            .groups = "drop")

club_seasons &lt;- payroll |&gt;
  inner_join(top_three, by = c("year", "team_id")) |&gt;
  inner_join(performance, by = c("year", "team_id")) |&gt;
  filter(total_pay &gt; 0, players &gt;= 3, matches &gt; 0) |&gt;
  mutate(top_three_share = top_three_pay / total_pay,
         xgd_per_match = (xg_for - xg_against) / matches) |&gt;
  left_join(teams, by = "team_id")

coverage &lt;- club_seasons |&gt;
  group_by(year) |&gt;
  summarize(clubs = n(), fewest_matches = min(matches),
            most_matches = max(matches), .groups = "drop")
coverage


